function statusForScore(score: number): { label: string; color: string; icon: LucideIcon } {
  if (score >= 91) return { label: "CRITICAL THREATS DETECTED", color: "critical", icon: ShieldAlert };
  if (score >= 76) return { label: "HIGH-RISK ACTIVITY", color: "high", icon: AlertTriangle };
  if (score >= 51) return { label: "SECURITY WARNING", color: "warning", icon: AlertCircle };
  return { label: "SYSTEM SECURE", color: "safe", icon: ShieldCheck };
}

function severityTone(severity: Severity): string {
  return severity.toLowerCase().replace(" ", "-");
}

function timeNow(): string {
  return new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
}

function formatScore(score: number): string {
  return `${Math.round(score)}`;
}

function Button({ children, variant = "primary", size = "md", className = "", onClick, disabled, type = "button", title }: { children: ReactNode; variant?: "primary" | "secondary" | "ghost" | "danger"; size?: "sm" | "md" | "lg"; className?: string; onClick?: () => void; disabled?: boolean; type?: "button" | "submit"; title?: string }) {
  return <button type={type} title={title} disabled={disabled} onClick={onClick} className={`cs-button cs-button-${variant} cs-button-${size} ${className}`}>{children}</button>;
}

function IconButton({ icon: Icon, label, onClick, active = false, className = "" }: { icon: LucideIcon; label: string; onClick?: () => void; active?: boolean; className?: string }) {
  return <button aria-label={label} title={label} onClick={onClick} className={`cs-icon-button ${active ? "is-active" : ""} ${className}`}><Icon size={17} strokeWidth={1.8} /></button>;
}

function SeverityBadge({ severity }: { severity: Severity }) {
  return <span className={`severity-badge severity-${severityTone(severity)}`}><span className="severity-dot" />{severity.toUpperCase()}</span>;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="section-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="heading-action">{action}</div>}</div>;
}

function StatCard({ label, value, detail, trend, icon: Icon, tone = "blue", onClick }: { label: string; value: string; detail: string; trend?: "up" | "down" | "neutral"; icon: LucideIcon; tone?: string; onClick?: () => void }) {
  return <button onClick={onClick} className={`stat-card tone-${tone}`}><div className="stat-card-top"><span className="stat-label">{label}</span><span className="stat-icon"><Icon size={17} /></span></div><div className="stat-value">{value}</div><div className="stat-foot"><span className={trend === "up" ? "trend-up" : trend === "down" ? "trend-down" : "trend-neutral"}>{trend === "up" && <ArrowUpRight size={13} />}{trend === "down" && <ArrowDownRight size={13} />}{detail}</span><span className="stat-period">vs last cycle</span></div></button>;
}

function Panel({ children, className = "", title, subtitle, action }: { children: ReactNode; className?: string; title?: string; subtitle?: string; action?: ReactNode }) {
  return <section className={`panel ${className}`}>{(title || action) && <div className="panel-header"><div>{title && <h3>{title}</h3>}{subtitle && <span>{subtitle}</span>}</div>{action}</div>}{children}</section>;
}

function Sparkline({ data, color = "var(--accent)" }: { data: number[]; color?: string }) {
  const points = data.map((value, index) => `${(index / Math.max(data.length - 1, 1)) * 100},${100 - value}`).join(" ");
  return <svg className="sparkline" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline points={points} fill="none" stroke={color} strokeWidth="3" vectorEffect="non-scaling-stroke" /></svg>;
}

function ThreatGauge({ score, size = "large" }: { score: number; size?: "large" | "small" }) {
  const radius = size === "large" ? 58 : 42;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (Math.min(score, 100) / 100) * circumference;
  const scoreStatus = statusForScore(score);
  return <div className={`threat-gauge threat-gauge-${size}`}><svg viewBox="0 0 160 160" role="img" aria-label={`Threat score ${score} out of 100`}><circle className="gauge-track" cx="80" cy="80" r={radius} /><circle className={`gauge-progress gauge-${scoreStatus.color}`} cx="80" cy="80" r={radius} strokeDasharray={circumference} strokeDashoffset={offset} /></svg><div className="gauge-center"><strong>{formatScore(score)}</strong><span>of 100</span><small>{scoreStatus.label.split(" ")[0]}</small></div></div>;
}

function MiniBar({ value, tone = "blue" }: { value: number; tone?: string }) {
  return <div className="mini-bar"><span className={`mini-bar-fill fill-${tone}`} style={{ width: `${Math.min(value, 100)}%` }} /></div>;
}

